//! 🧪️ Shared owned serde_json witnesses exercise the real Draw source issuer and exact cursor backing retirement.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
use semio_framework_io_ports::erase_child_admission_source;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:256}}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧪️.json")).unwrap()}
fn decode(value:&serde_json::Value)->DrawingSnapshot{serde_json::from_value(value.clone()).unwrap()}
fn patched(base:&serde_json::Value,patches:&serde_json::Value)->serde_json::Value{let mut value=base.clone();for patch in patches.as_array().unwrap(){let path=patch["path"].as_str().unwrap();if patch["op"]=="remove"{assert_eq!(path,"/artboard");value.as_object_mut().unwrap().remove("artboard");}else{*value.pointer_mut(path).unwrap()=patch["value"].clone()}}value}
fn run(document:DrawingSnapshot,cancel:Option<usize>)->(Option<&'static str>,usize,bool){let saved=document.clone();let(mut source,_)=RetainedCloneSource::admit_owned(document,(),grant()).unwrap_or_else(|_|panic!("genuine Drawing original admission"));let(mut cursor,birth)=DRAWING_ADMITTER.begin(grant()).unwrap();let mut capacity=birth.retained_capacity_bytes;let mut released=0;let mut done=false;let mut canvas=false;let mut error=None;let mut turns=0;for _ in 0..cancel.unwrap_or(1000000){let original=erase_child_admission_source(source.borrow(),0x4348494c);for denied in [Default::default(),RetainedCloneGrant{maximum_copy_bytes:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()},RetainedCloneGrant{maximum_items:0,..grant()}]{let step=cursor.advance(original,denied).unwrap();assert_eq!(step.progress,Default::default());}let step=cursor.advance(original,grant()).unwrap();assert!(step.progress.fits(grant()));capacity+=step.progress.retained_capacity_bytes;if let Some(board)=step.canvas{assert!(board.width.is_finite()&&board.width>0.0&&board.height.is_finite()&&board.height>0.0);canvas=true}turns+=1;if step.done{done=true;error=step.error;break}}if cancel.is_none(){assert!(done)}if turns>0{assert!(cursor.next_demand(erase_child_admission_source(source.borrow(),0x4348494d),grant().maximum_copy_bytes).is_err())}cursor.begin_close();let mut closed=0;while !cursor.terminal_is_empty(){let d=cursor.close_demand(grant().maximum_copy_bytes).unwrap();if d.release_bytes>0{let denied=cursor.close_step(RetainedCloneGrant{maximum_release_bytes:0,..grant()}).unwrap();assert_eq!(denied.progress(),Default::default())}let p=cursor.close_step(grant()).unwrap().progress();assert!(p.fits(grant()));capacity+=p.retained_capacity_bytes;released+=p.released_bytes;closed+=1;assert!(closed<1000000)}assert_eq!(released,capacity);assert_eq!(source.try_authority().unwrap(),&saved);while !source.terminal_is_empty(){source.close_step(grant()).unwrap();closed+=1;assert!(closed<2000000)}(error,turns,canvas)}
#[test]
fn original_drawing_admission_matches_the_portable_owned_oracle(){assert!(DRAWING_ADMITTER.begin(Default::default()).is_err());let corpus=fixture();for case in corpus["cases"].as_array().unwrap(){let value=patched(&corpus["base"],&case["patch"]);let expected=case["valid"].as_bool().unwrap();let(error,_,canvas)=run(decode(&value),None);assert_eq!(error.is_none(),expected,"{}",case["name"]);if expected{assert_eq!(canvas,value.get("artboard").is_some(),"{}",case["name"]);}}}
#[test]
fn original_drawing_cancellation_and_paged_key_comparison_remain_paired(){let corpus=fixture();for cancel in [0,1,2,3,5,20,100,200]{run(decode(&corpus["base"]),Some(cancel));}let mut value=corpus["base"].clone();let prefix="Ω".repeat(4096);value["layers"][0]["id"]=serde_json::json!(format!("{prefix}a"));value["layers"][1]["id"]=serde_json::json!(format!("{prefix}b"));value["layers"][3]["children"][1]=serde_json::json!(format!("{prefix}b"));let(error,turns,_)=run(decode(&value),None);assert!(error.is_none());assert!(turns>128);value["layers"][1]["id"]=value["layers"][0]["id"].clone();assert!(run(decode(&value),None).0.is_some());}
#[test]
fn another_original_issuer_or_native_owner_type_cannot_replace_the_source(){let corpus=fixture();let(mut source,_)=RetainedCloneSource::admit_owned(decode(&corpus["base"]),(),grant()).unwrap_or_else(|_|panic!("first source"));let(mut other,_)=RetainedCloneSource::admit_owned(decode(&corpus["base"]),(),grant()).unwrap_or_else(|_|panic!("second source"));let(mut cursor,_)=DRAWING_ADMITTER.begin(grant()).unwrap();cursor.advance(erase_child_admission_source(source.borrow(),1),grant()).unwrap();assert!(cursor.next_demand(erase_child_admission_source(other.borrow(),1),grant().maximum_copy_bytes).is_err());assert!(cursor.next_demand(erase_child_admission_source(source.borrow().project(2,|s|&s.id),1),grant().maximum_copy_bytes).is_err());cursor.begin_close();while !cursor.terminal_is_empty(){cursor.close_step(grant()).unwrap();}while !source.terminal_is_empty(){source.close_step(grant()).unwrap();}while !other.terminal_is_empty(){other.close_step(grant()).unwrap();}}

#[test]
fn deep_original_ancestry_is_iterative_and_cancellable(){let corpus=fixture();let mut value=corpus["base"].clone();for at in 0..128{let mut group=corpus["base"]["layers"][0].clone();group["id"]=serde_json::json!(format!("deep-{at}"));group["children"]=value["layers"].take();value["layers"]=serde_json::json!([group]);}assert!(run(decode(&value),None).0.is_none());for cancel in [3,20,100,200]{run(decode(&value),Some(cancel));}}
